802	    persist_segments =
803	        get_all_persist_segments();  // will not return writing segment
804	    // after leave this scope, writing action is allowed
805	  }
806	
807	  if (persist_segments.size() == 0) {
808	    // no need to optimize
809	    return Status::OK();
810	  }
811	
812	  // build segment compact task
813	  auto delete_store_clone = delete_store_->clone();
814	  auto tasks =
815	      build_compact_task(schema_, persist_segments, options.concurrency_,
816	                         delete_store_clone->make_filter());
817	
818	  // execute segment compact task
819	  auto s = execute_compact_task(tasks);
820	  CHECK_RETURN_STATUS(s);
821	
822	  {
823	    // forbidden writing for updating version
824	    // writing action may trigger updating version where confict occurs
825	    std::lock_guard write_lock(write_mtx_);
826	
827	    Version new_version = version_manager_->get_current_version();
828	
829	    for (auto &task : tasks) {
830	      auto task_info = task->task_info();
831	
832	      if (std::holds_alternative<CompactTask>(task_info)) {
833	        auto compact_task = std::get<CompactTask>(task_info);
834	
835	        // 0. check if has output segment meta
836	        if (compact_task.output_segment_meta_) {
837	          // 1. rename built tmp segments
838	          auto tmp_segment_id = compact_task.output_segment_id_;
839	          auto tmp_segment_path =
