461	Status SegmentImpl::Open(const SegmentOptions &options) {
462	  options_ = options;
463	  options_.enable_mmap_ = version_manager_->get_current_version().enable_mmap();
464	
465	  filter_ =
466	      std::make_shared<SegmentIndexFilter>(delete_store_, shared_from_this());
467	
468	  // load persist forward blocks
469	  auto s = load_persist_scalar_blocks();
470	  CHECK_RETURN_STATUS(s);
471	
472	  // load scalar indexes
473	  s = load_scalar_index_blocks();
474	  CHECK_RETURN_STATUS(s);
475	
476	  // load FTS indexes
477	  s = open_fts_indexers(false);
478	  CHECK_RETURN_STATUS(s);
479	
480	  // load vector indexes
481	  s = load_vector_index_blocks();
482	  CHECK_RETURN_STATUS(s);
483	
484	  auto writing_block = segment_meta_->writing_forward_block();
485	  if (!writing_block.has_value() && !options_.read_only_) {
486	    return Status::InternalError(
487	        "No writing block found when in writing mode.");
488	  }
489	
490	  if (writing_block.has_value()) {
491	    // init doc_id_allocator and block_id_allocator
492	    doc_id_allocator_ = writing_block.value().min_doc_id();
493	    BlockID max_block_id{writing_block.value().id()};
494	    for (auto &block : segment_meta_->persisted_blocks()) {
495	      max_block_id = std::max(max_block_id, block.id());
496	    }
497	    block_id_allocator_ = max_block_id + 1;
498	
499	    // recover writing block
500	    s = recover();
501	    CHECK_RETURN_STATUS(s);
502	  } else {
503	    // Update block_id_allocator_
504	    BlockID max_block_id{0};
505	    auto &persist_blocks = segment_meta_->persisted_blocks();
506	    for (const auto &block : persist_blocks) {
507	      max_block_id = std::max(max_block_id, block.id());
508	    }
509	    block_id_allocator_.store(max_block_id + 1);
510	  }
511	
512	  fresh_persist_block_offset();
513	
514	  fresh_persist_chunked_array();
515	
516	  return Status::OK();
517	}
