527	  std::vector<std::string> schema_forward_fields =
528	      collection_schema_->forward_field_names();
529	  columns.insert(columns.end(), schema_forward_fields.begin(),
530	                 schema_forward_fields.end());
531	
532	  segment_meta_->set_writing_forward_block(
533	      {block_id, BlockType::SCALAR, min_doc_id, min_doc_id, 0, columns});
534	  auto vector_fields = collection_schema_->vector_fields();
535	  for (auto &field : vector_fields) {
