143	int LocalWalFile::prepare_for_read() {
144	  CHECK_STATUS(opened_, true);
145	  if (!file_.seek(0, ailego::File::Origin::Begin)) {
146	    return -1;
147	  }
148	  int read_size = file_.read((void *)&header_, sizeof(header_));
149	  if (read_size != sizeof(header_)) {
150	    WLOG_ERROR("Wal read header error.");
151	    return -1;
152	  }
153	  if (header_.wal_version != 0UL) {
154	    WLOG_ERROR("Wal version not support error.");
155	    return -1;
156	  }
157	  return 0;
158	}
