std::string LocalWalFile::next() {
  WalRecord record;
  if (read_record(record) > 0) {
    uint32_t tmp_crc = ailego::Crc32c::Hash(
        reinterpret_cast<const void *>(record.content_.data()), record.length_,
        0);
