      return std::move(record.content_);
    } else {
      WLOG_ERROR(
          "Wal next error. record.length_[%zu] crc_[%zu] != tmp_crc[%zu]",
          (size_t)record.length_, (size_t)record.crc_, (size_t)tmp_crc);
