39	
40	static std::string optimizer_bin_;
41	const std::string collection_name_{"optimize_recovery_test"};
42	const std::string dir_path_{"optimize_recovery_test_db"};
43	const zvec::CollectionOptions options_{false, true, 256 * 1024};
44	const int batch_size{50};
45	const int num_batches{1000};
