48	static std::string LocateOptimizeGenerator() {
49	  return LocateBinary("collection_optimizer");
50	}
51	
52	
53	void ExecuteOptimizer(const std::string &path, int kill_after_seconds = -1) {
54	  bool should_crash = kill_after_seconds >= 0;
55	
56	#ifdef _WIN32
57	  std::string cmd_str = optimizer_bin_ + " --path " + path;
58	
59	  STARTUPINFOA si = {sizeof(si)};
60	  PROCESS_INFORMATION pi;
61	
62	  std::cout << cmd_str << std::endl;
63	
64	  std::vector<char> cmd_buf(cmd_str.begin(), cmd_str.end());
65	  cmd_buf.push_back('\0');
66	  if (!CreateProcessA(NULL, cmd_buf.data(), NULL, NULL, FALSE, 0, NULL, NULL,
67	                      &si, &pi)) {
68	    FAIL() << "CreateProcess failed (" << GetLastError() << ")";
69	  }
70	
71	  if (should_crash) {
72	    std::this_thread::sleep_for(std::chrono::seconds(kill_after_seconds));
73	    DWORD wait_result = WaitForSingleObject(pi.hProcess, 0);
74	    if (wait_result == WAIT_TIMEOUT) {
75	      TerminateProcess(pi.hProcess, 1);
76	    }
77	  }
78	
79	  WaitForSingleObject(pi.hProcess, INFINITE);
80	
81	  DWORD exit_code;
82	  GetExitCodeProcess(pi.hProcess, &exit_code);
83	  CloseHandle(pi.hProcess);
84	  CloseHandle(pi.hThread);
85	
86	  if (!should_crash) {
87	    ASSERT_EQ(exit_code, 0) << "Process failed with exit code: " << exit_code;
88	  }
89	
90	#else
91	  pid_t pid = fork();
92	  ASSERT_GE(pid, 0);
93	
94	  if (pid == 0) {
95	    char arg_path[] = "--path";
96	    char *args[] = {const_cast<char *>(optimizer_bin_.c_str()), arg_path,
97	                    const_cast<char *>(path.c_str()), nullptr};
98	    execvp(args[0], args);
99	    perror("execvp failed");
100	    _exit(1);
101	  }
102	
103	  int status;
104	  if (should_crash) {
105	    std::this_thread::sleep_for(std::chrono::seconds(kill_after_seconds));
106	    if (kill(pid, 0) == 0) {
107	      kill(pid, SIGKILL);
108	    }
109	    waitpid(pid, &status, 0);
110	  } else {
111	    waitpid(pid, &status, 0);
112	    ASSERT_TRUE(WIFEXITED(status))
113	        << "Child process did not exit normally. Terminated by signal?";
114	    int exit_code = WEXITSTATUS(status);
115	    ASSERT_EQ(exit_code, 0) << "optimizer failed with exit code: " << exit_code;
